from pathlib import Path
q=json.loads(Path('previous_spatial.json').read_text());fine=json.loads(Path('fine512.json').read_text());coarse=json.loads(Path('base384_2000.json').read_text());pilot=json.loads(Path('retention_pilot.json').read_text());r1000=json.loads(Path('base384_1000.json').read_text())
