inv=fine['full_domain_null_inventory'];idx=fine['topology_last_index'];ts=fine['timeseries']; assert inv[-1]['index']==idx and ts[idx]['reconnected_flux_from_by']>=.05 and ts[idx-1]['reconnected_flux_from_by']<.05
