out={'S2000_fine':{'mesh':512,'meshes':[256,384,512],'rates':rates.tolist(),'relative_changes':ch.tolist(),'mesh_gate':bool(ch[-1]<ch[-2] and ch[-1]<=.05),'terms':terms,'u':u,'rate_interval':[R*(1-u),R*(1+u)],'min_sheet_halfwidth_cells':min(v['sheet_halfwidth_cells'] for v in fine['extended_timeseries']),'topology':{'frame_count':len(inv),'counts':sorted(set((sum(z[2]=='X' for z in row['nulls']),sum(z[2]=='O' for z in row['nulls'])) for row in inv)),'last_index':idx,'last_time':ts[idx]['time'],'last_flux':ts[idx]['reconnected_flux_from_by'],'preceding_flux':ts[idx-1]['reconnected_flux_from_by']}},'S1000_fine':qa,'matched_384_to512':comparisons,'proposed_production384':{'S2000_relative_transported_allowance':transport,'absolute_fine_allowance':R*u,'absolute_grid_shift':abs(R-Rp),'formula':'epsilon384=R512*u512+abs(R512-R384); use max with fresh production direct error sum; add any excess production cadence term. All finest-control gates unchanged.','calibration_only_slope_interval':[lower,upper],'status':'Not evidence; numerical qualification only'},'retention':{'pilot_frame_count':pilot['magnetic_retention_check']['frame_count'],'fine_frame_count':fine['magnetic_retention_check']['frame_count'],'all_readback_equal':True},'cadence_changes':json.loads(Path('cadence_comparison.json').read_text()),'source_experiments':['exp_58adb12d461c94104daeff23','exp_cd08ebc4f1287d48388eddc6','exp_c99f4a2aba5c70b7330e4ada'],'limitations':['Transferred measured256CFL contribution; no independent512CFL control.','Empirical error envelope, not rigorous continuum bound.','Separate floor/energyFix accounting unavailable.','No promotion of exploratory values to hypothesis evidence.']}
